#!/usr/bin/env node
// Precompiles the Engineering JSON Schemas with ajv standalone, so the browser never needs a runtime
// schema compiler (which uses new Function and would need 'unsafe-eval' in the Content Security Policy).
// Usage: node scripts/build-validators.mjs [--check]   (--check fails if the generated file is out of date)
import { readFileSync, writeFileSync } from 'node:fs';
import Ajv from 'ajv';
import standaloneCode from 'ajv/dist/standalone/index.js';

const dir = 'src/engineering/schemas';
const names = ['manifest', 'review', 'graph', 'trace'];
const ajv = new Ajv({ code: { source: true, esm: true }, allErrors: true, strict: true });
const exportsMap = {};
for (const n of names) {
  const schema = JSON.parse(readFileSync(`${dir}/${n}.schema.json`, 'utf8'));
  ajv.addSchema(schema, n);
  exportsMap[`validate_${n}`] = n;
}
// ajv's generated code calls require() for its string-length helper. Inline the same helper instead,
// so the output is plain ESM and no ajv runtime file ships to the browser.
const UCS2 = `function ucs2length(str) { const len = str.length; let length = 0; let pos = 0; while (pos < len) { length++; const value = str.charCodeAt(pos++); if (value >= 0xd800 && value <= 0xdbff && pos < len) { const extra = str.charCodeAt(pos); if ((extra & 0xfc00) === 0xdc00) pos++; } } return length; }\n`;
const generated = standaloneCode(ajv, exportsMap).replaceAll('require("ajv/dist/runtime/ucs2length").default', 'ucs2length');
if (generated.includes('require(')) throw new Error('generated validators still contain require()');
const code = '// @ts-nocheck\n/* eslint-disable */\n// Generated by scripts/build-validators.mjs from the *.schema.json files. Do not edit by hand.\n' + UCS2 + generated;
const target = `${dir}/validators.generated.js`;
if (process.argv.includes('--check')) {
  let current = '';
  try { current = readFileSync(target, 'utf8'); } catch { /* missing */ }
  if (current !== code) { console.error('validators.generated.js is out of date. Run: npm run build:validators'); process.exit(1); }
  console.log('validators.generated.js is up to date');
} else {
  writeFileSync(target, code);
  console.log(`wrote ${target}`);
}
